function validate([n, meetings, firstPerson]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (!Array.isArray(meetings) || meetings.length < 1 || meetings.length > 100000) return 'meetings needs 1 to 10^5 entries.';
  for (const meeting of meetings) {
    if (!Array.isArray(meeting) || meeting.length !== 3 || !meeting.every(Number.isInteger)) return 'Each meeting is [x, y, time] of integers.';
    const [x, y, time] = meeting;
    if (x < 0 || x >= n || y < 0 || y >= n) return 'People in a meeting are numbered 0 to n - 1.';
    if (x === y) return 'A meeting needs two different people.';
    if (time < 1 || time > 100000) return 'Each time is between 1 and 10^5.';
  }
  if (!Number.isInteger(firstPerson) || firstPerson < 1 || firstPerson > n - 1) return 'firstPerson is between 1 and n - 1.';
  return null;
}

