function findAllPeople(n, meetings, firstPerson) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA < rootB) parent[rootB] = rootA;
    else parent[rootA] = rootB;
  };

  union(0, firstPerson);
  meetings.sort((a, b) => a[2] - b[2]);

  let start = 0;
  while (start < meetings.length) {
    const time = meetings[start][2];
    let end = start;
    while (end < meetings.length && meetings[end][2] === time) {
      union(meetings[end][0], meetings[end][1]);
      end++;
    }
    for (let i = start; i < end; i++) {
      const [x, y] = meetings[i];
      if (find(x) !== 0) parent[x] = x;
      if (find(y) !== 0) parent[y] = y;
    }
    start = end;
  }

  const result = [];
  for (let person = 0; person < n; person++) {
    if (find(person) === 0) result.push(person);
  }
  return result;
}

