function findAllPeople(n, meetings, firstPerson) {
  const knows = new Array(n).fill(false);
  knows[0] = true;
  knows[firstPerson] = true;
  const times = [...new Set(meetings.map(m => m[2]))].sort((a, b) => a - b);
  for (const t of times) {
    let changed = true;
    while (changed) {
      changed = false;
      for (const [x, y, time] of meetings) {
        if (time !== t || knows[x] === knows[y]) continue;
        knows[x] = true;
        knows[y] = true;
        changed = true;
      }
    }
  }
  const out = [];
  knows.forEach((k, i) => { if (k) out.push(i); });
  return out;
}

