function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 : 2 + Math.floor(rand() * 7);
  const m = large ? 2000 : 1 + Math.floor(rand() * 10);
  const maxTime = large ? 300 : 1 + Math.floor(rand() * 4);
  const meetings = [];
  for (let i = 0; i < m; i++) {
    const x = Math.floor(rand() * n);
    let y = Math.floor(rand() * (n - 1));
    if (y >= x) y++;
    meetings.push([x, y, 1 + Math.floor(rand() * maxTime)]);
  }
  const firstPerson = 1 + Math.floor(rand() * (n - 1));
  return [n, meetings, firstPerson];
}
